; ==================================================================
; NODE DATA STRUCTURES
; Each node has: type byte, data pointer, connection table pointer
; ==================================================================

; Node: Start - "gf_slow_start"
gameflow_node_gf_slow_start:
    db NODE_TYPE_START
    dw gameflow_node_gf_slow_start_data
    dw gameflow_node_gf_slow_start_conn

gameflow_node_gf_slow_start_data:
    dw gameflow_node_gf_slow_start_init    ; Initialization routine address
    db ((gameflow_node_gf_slow_start_init - #4000) / #2000)    ; Initialization routine bank

gameflow_node_gf_slow_start_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gf_slow_music
    db CONNECTION_END

; ------------------------------------------------------------------
; gameflow_node_gf_slow_start_init
; Initialization routine for Start node
; Initializes global variables and MSX systems
; ------------------------------------------------------------------
gameflow_node_gf_slow_start_init:
    ; === Core Game Systems Initialization (ALWAYS required) ===
    call init_game_systems

    ret

; Node: Music - "gf_slow_music"
gameflow_node_gf_slow_music:
    db NODE_TYPE_MUSIC
    dw gameflow_node_gf_slow_music_data
    dw gameflow_node_gf_slow_music_conn

gameflow_node_gf_slow_music_data:
    db 1, 0, 1    ; command, track index, loop flag

gameflow_node_gf_slow_music_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gf_slow_end
    db CONNECTION_END

; Node: End - "gf_slow_end"
gameflow_node_gf_slow_end:
    db NODE_TYPE_END
    dw gameflow_no_data
    dw gameflow_node_gf_slow_end_conn

gameflow_node_gf_slow_end_conn:
    db CONNECTION_DEFAULT
    dw 0
    db CONNECTION_END


